# JRE is kept in the optional discovery shelf, not assigned as compulsory daily content.
optional=[dict(id='jre-neil-tyson-preview',title='Joe Rogan Experience #1658 — Neil deGrasse Tyson',provider='Joe Rogan Experience',family='Joe Rogan Experience',url='https://www.youtube.com/watch?v=qiP1E6iAVS8',topics=['astronomy','space','science','universe'],level='C1',transcript='Captions/transcript not verified',duration='Long-form episode; no compulsory segment assigned',task='Optional listening only after a parent/teacher has previewed the episode and confirmed suitability.',safe='PREVIEW_REQUIRED; JRE may contain explicit language or adult discussion; never part of the required 84-day path',embed='official-youtube-link-only',eligible_for_daily=False)]

# Select a resource using topic tags and avoid very short-interval repetition.
provider_priority=['TED-Ed','TED','Huberman Lab','The Diary of a CEO']
assignments=[]
recent=[]
for i,day in enumerate(days,1):
    theme=(day.get('theme') or '').lower()
    # tokens are deliberately simple and auditable
    tokens=set(re.findall(r'[a-z]+',theme))
    best=None; best_score=-10**9
    for item in items:
        tagset=set(item['topics'])
        overlap=len(tokens & tagset)
        # broader semantic bonuses
        if any(t in theme for t in ['sleep','memory','health','cognition']) and any(t in tagset for t in ['sleep','memory','brain']): overlap+=2
        if any(t in theme for t in ['space','astronomy']) and 'space' in tagset: overlap+=3
        if 'language' in theme and 'language' in tagset: overlap+=3
        if any(t in theme for t in ['attention','digital','media']) and 'attention' in tagset: overlap+=2
        if any(t in theme for t in ['food','nutrition']) and 'food' in tagset: overlap+=2
        # penalise exact reuse in immediate few days and balance sources
        penalty=3 if item['id'] in recent[-3:] else (1 if item['id'] in recent[-6:] else 0)
        provider_used=sum(1 for a in assignments[-12:] if a['provider']==item['family'])
        score=overlap*4-penalty-provider_used*0.06
        if score>best_score:
            best_score=score;best=item
    if best is None: best=items[i%len(items)]
    recent.append(best['id'])
    # cycle listening purpose so revisiting a video is a new deliberate task
    foci=['gist + central claim','signposting + sequence','example vs evidence','cause/effect + qualification','speaker stance + paraphrase','summary + key vocabulary']
    focus=foci[(i-1)%len(foci)]
    assignment={
      'day':i,'resource_id':best['id'],'title':best['title'],'provider':best['family'],'url':best['url'],
      'level_estimate':best['level'],'level_basis':'editorial estimate, not an official CEFR label',
      'duration_note':best['duration'],'segment_start':best.get('start'),'segment_end':best.get('end'),
      'transcript_caption_status':best['transcript'],'listening_focus':focus,
      'study_task':best['task'],'required_or_optional':'optional external companion; internal daily audio/script/questions remain the core task',
      'age_suitability':best['safe'],'embed_mode':best['embed'],
      'repeat_design':'When this source recurs, a different listening focus is assigned; it is not counted as a new unique video.'
    }
    assignments.append(assignment)
    day['resources']['listening']['stage47_companion']=assignment
    # Add resource inventory metadata to all four mandatory skill cards.
    task1=day['resources']['writing']['task1']
    day['resources']['writing']['task1']['stage47_type_guide']=task1['type']
    day['resources']['writing']['task1']['dataset_status']='Original IELTS Boost fictional dataset; not Barron’s/Cambridge copied content.'

# top-level stage47 pack metadata
