# old generic TED search links replaced in day cards with exact companion assignment while retaining fallback source archive.
for i,d in enumerate(days):
    l=d['resources']['listening']
    l['verification_status']='stage47_individual_official_companion_selected; transcript/caption availability is recorded per item'
    l['resource_selection_rule']='Use the exact Stage 47 companion card for optional external listening; the 84-day original IELTS Boost script/audio/questions remain the required in-app core.'

