with (root/'STAGE47_RESOURCE_MAPPING_UZ.csv').open('w',newline='',encoding='utf-8-sig') as f:
    w=csv.DictWriter(f,fieldnames=['day','theme','task1_type','resource_title','provider','url','level_estimate','listening_focus','segment_start','segment_end','transcript_caption_status','age_suitability','resource_id'])
    w.writeheader()
    for i,d in enumerate(days):
        a=assignments[i]
        w.writerow({'day':i+1,'theme':d.get('theme',''),'task1_type':d['resources']['writing']['task1']['type'],'resource_title':a['title'],'provider':a['provider'],'url':a['url'],'level_estimate':a['level_estimate'],'listening_focus':a['listening_focus'],'segment_start':a['segment_start'] or '', 'segment_end':a['segment_end'] or '', 'transcript_caption_status':a['transcript_caption_status'],'age_suitability':a['age_suitability'],'resource_id':a['resource_id']})
